using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Markup;
using Microsoft.Win32;
namespace ClearSpace {
public sealed class SettingsView {public FrameworkElement Root;public Func<bool> TryLeave;}
public static class RuleCenter {
 public static SettingsView Create(Window owner,CleanerSettings settings,DiscoveryResult discovery,Action changed,Action back,Action about,Action<CleanerSettings> persist=null,Action<string> openLocation=null,Action restartAdministrator=null,Action<string> notify=null){
  UserControl w;
  using(var resource=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("ClearSpace.Settings.xaml"))w=(UserControl)XamlReader.Load(resource);
  Action<string> message=value=>{((TextBlock)w.FindName("Status")).Text=value;((FrameworkElement)w.FindName("SettingsStatusFrame")).Visibility=Visibility.Collapsed;if(notify!=null)notify(value);};
  Action<string> progress=value=>{((TextBlock)w.FindName("Status")).Text=value;((FrameworkElement)w.FindName("SettingsStatusFrame")).Visibility=Visibility.Visible;};
  bool useWinapp2=settings.UseWinapp2;
  Action persistSettings=()=>{if(persist!=null)persist(settings);else settings.Save();};Func<string,TextBox> text=n=>(TextBox)w.FindName(n);Func<string,Button> button=n=>(Button)w.FindName(n);
  var language=(ComboBox)w.FindName("LanguageChoice");language.ItemsSource=new[]{"简体中文","English"};language.SelectedIndex=UiText.Normalize(settings.Language)=="en"?1:0;
  bool restoringLanguage=false;
  language.SelectionChanged+=(s,e)=>{if(restoringLanguage)return;string previous=settings.Language;try{settings.Language=language.SelectedIndex==1?"en":"zh-CN";persistSettings();UiText.SetLanguage(settings.Language);changed();message("语言设置已保存。");}catch(Exception ex){settings.Language=previous;restoringLanguage=true;try{language.SelectedIndex=UiText.Normalize(previous)=="en"?1:0;}finally{restoringLanguage=false;}UiText.SetLanguage(previous);message("语言设置未保存："+ex.Message);}};
  var administrator=(Button)w.FindName("AdminMode");administrator.IsEnabled=!App.IsAdmin()&&restartAdministrator!=null;((TextBlock)w.FindName("PrivilegeState")).Text=App.IsAdmin()?"当前已以管理员身份运行。":"当前使用普通权限。";
  administrator.Click+=(s,e)=>{if(restartAdministrator!=null)restartAdministrator();};button("AboutButton").Click+=(s,e)=>about();button("SettingsBack").Click+=(s,e)=>back();
  var store=new RuleStore();var communityStore=new Winapp2Store();var provider=(ComboBox)w.FindName("RuleProvider");var state=(TextBlock)w.FindName("LibraryState");var hint=(TextBlock)w.FindName("SourceHint");var status=(TextBlock)w.FindName("Status");var automatic=(CheckBox)w.FindName("Automatic");var portable=(ListBox)w.FindName("Portable");var apps=(ListBox)w.FindName("Apps");
  Action refresh=()=>{if(useWinapp2){var pack=communityStore.Current();state.Text="Winapp2 "+pack.Version+" · "+pack.Entries.Count+" 条定义 · "+pack.Origin;hint.Text="社区规则用于常规扫描、高级自选，默认不选且先备份。系统核心、未知指令及社区注册表删除不会执行。";}else{var pack=store.Current();state.Text="规则库 "+pack.Pack.Version+" · "+pack.Pack.Rules.Count+" 条应用规则 · "+pack.Trust;hint.Text="在线 JSON 更新需发布者签名；未签名本地规则需确认导入。外部规则用于常规扫描、高级自选。";}portable.ItemsSource=settings.PortableDirectories.ToArray();button("Compatibility").Visibility=useWinapp2?Visibility.Visible:Visibility.Collapsed;};
  string jsonDraft=RuleSourceAddresses.Json(settings.UpdateUrl);settings.UpdateUrl=jsonDraft;bool previousSource=useWinapp2;provider.ItemsSource=new[]{"Winapp2.ini · 社区规则","签名 JSON · 自定义规则"};provider.SelectedIndex=useWinapp2?0:1;
  text("UpdateUrl").Text=useWinapp2?Winapp2Store.Url:jsonDraft;text("UpdateUrl").IsReadOnly=useWinapp2;automatic.Content="每 7 天自动检查一次";automatic.IsChecked=settings.AutomaticUpdates;
  provider.SelectionChanged+=(s,e)=>{if(!previousSource)jsonDraft=RuleSourceAddresses.Json(text("UpdateUrl").Text);useWinapp2=provider.SelectedIndex==0;previousSource=useWinapp2;text("UpdateUrl").Text=useWinapp2?Winapp2Store.Url:jsonDraft;text("UpdateUrl").IsReadOnly=useWinapp2;if(!useWinapp2&&String.IsNullOrWhiteSpace(jsonDraft))automatic.IsChecked=false;refresh();message("规则来源尚未保存，请点击“保存规则设置”。");};refresh();
  text("RecoveryPath").Text=String.IsNullOrEmpty(settings.RecoveryDirectory)?FileRecovery.DefaultDirectory():settings.RecoveryDirectory;var identities=discovery==null?new List<ApplicationIdentity>():discovery.Applications;apps.ItemsSource=identities;text("AppSearch").ToolTip="搜索应用名、发行商或程序路径";text("AppSearch").TextChanged+=(s,e)=>apps.ItemsSource=identities.Where(a=>a.SearchText.IndexOf(text("AppSearch").Text,StringComparison.OrdinalIgnoreCase)>=0).ToList();apps.SelectionChanged+=(s,e)=>{var a=apps.SelectedItem as ApplicationIdentity;button("OpenApplication").IsEnabled=ApplicationLocations.Resolve(a)!=null;text("AppEvidence").Text=a==null?"":RuleStore.Describe(a)+"\n产品："+a.Product+"\n公司："+a.Company+"\n安装目录："+a.InstallDirectory;};if(identities.Count==0)text("AppEvidence").Text="常规扫描后会显示应用发现结果。";
  button("OpenApplication").Click+=(s,e)=>{try{string location=ApplicationLocations.Resolve(apps.SelectedItem as ApplicationIdentity);if(location==null)throw new IOException("应用文件或目录已不存在");if(openLocation!=null)openLocation(location);else ApplicationLocations.Open(location);}catch(Exception ex){message("打开应用位置失败："+ex.Message);}};
  Action save=()=>{if(!useWinapp2){string url=RuleSourceAddresses.Json(text("UpdateUrl").Text);RuleSourceAddresses.Validate(url);jsonDraft=url;if(automatic.IsChecked==true&&url.Length==0)throw new InvalidDataException("自动检查需先填写发布地址");settings.UpdateUrl=url;}settings.UseWinapp2=useWinapp2;settings.AutomaticUpdates=automatic.IsChecked==true;persistSettings();};button("Save").Click+=(s,e)=>{try{save();changed();message("规则设置已保存，下次常规扫描生效。");}catch(Exception ex){message(ex.Message);}};
  CancellationTokenSource updateStop=null;bool updating=false,restoring=false;button("Check").Click+=async(s,e)=>{if(updating){updateStop.Cancel();return;}try{save();bool ini=useWinapp2;string url=settings.UpdateUrl;if(!ini&&String.IsNullOrWhiteSpace(url)){message("尚未配置 JSON 地址，可先导入本地规则包。");return;}updating=true;updateStop=new CancellationTokenSource();administrator.IsEnabled=false;provider.IsEnabled=button("Import").IsEnabled=button("Rollback").IsEnabled=false;button("Check").Content="取消更新";progress(ini?"从指定 Winapp2 仓库下载并检查格式…":"下载并验证发布者签名…");await Task.Run(()=>{if(ini)communityStore.Update(updateStop.Token);else store.Update(url,updateStop.Token);});refresh();changed();message("当前规则已就绪，重新扫描后生效。");}catch(Exception ex){message("更新未应用："+ex.Message);}finally{updating=false;administrator.IsEnabled=!App.IsAdmin()&&restartAdministrator!=null;provider.IsEnabled=button("Import").IsEnabled=button("Rollback").IsEnabled=true;button("Check").Content="检查更新";if(updateStop!=null)updateStop.Dispose();}};
  button("Import").Click+=(s,e)=>{var d=new OpenFileDialog{Filter=UiText.T("规则文件 (*.ini;*.json)|*.ini;*.json|Winapp2 (*.ini)|*.ini|JSON (*.json)|*.json"),Title=UiText.T("导入应用清理规则")};if(d.ShowDialog(owner)!=true)return;try{bool ini=Path.GetExtension(d.FileName).Equals(".ini",StringComparison.OrdinalIgnoreCase);if(new FileInfo(d.FileName).Length>(ini?Winapp2Store.MaxBytes:RuleStore.MaxBytes))throw new InvalidDataException("规则包过大");string raw=File.ReadAllText(d.FileName),description;if(ini){var parsed=Winapp2Parser.Parse(raw);description="Winapp2 "+parsed.Version+" / "+parsed.Entries.Count+" 条定义（社区未签名）。\n"+Winapp2Adapter.Analyze(parsed,Winapp2Environment.Windows()).Summary+"。\n支持项目默认不选，只供高级自选并先备份。";}else{var parsed=store.Read(raw,true);description=parsed.Pack.Version+" / "+parsed.Pack.Rules.Count+" 条规则，"+parsed.Trust+"。\n只供高级自选。";}if(UiText.Show(owner,"导入 "+description+"\n重新扫描后生效。","检查规则来源",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;if(ini)communityStore.Import(raw);else store.Import(raw,true);useWinapp2=ini;provider.SelectedIndex=ini?0:1;settings.UseWinapp2=ini;persistSettings();refresh();changed();message("导入完成。");}catch(Exception ex){message("未导入："+ex.Message);}};
  button("Export").Click+=(s,e)=>{var d=new SaveFileDialog{Filter=useWinapp2?"INI (*.ini)|*.ini":"JSON (*.json)|*.json",FileName=useWinapp2?"Winapp2.ini":"Clarity-rules.json"};if(d.ShowDialog(owner)==true)try{File.WriteAllText(d.FileName,useWinapp2?communityStore.Current().Raw:store.Current().Raw,new System.Text.UTF8Encoding(true));message("当前规则已导出。");}catch(Exception ex){message(ex.Message);}};
  button("Compatibility").Click+=(s,e)=>{var d=new SaveFileDialog{Filter=UiText.T("兼容报告 (*.txt)|*.txt"),FileName="Winapp2-兼容报告.txt"};if(d.ShowDialog(owner)==true)try{var pack=communityStore.Current();var report=Winapp2Adapter.Analyze(pack,Winapp2Environment.Windows());File.WriteAllLines(d.FileName,new[]{"Winapp2 "+pack.Version,"来源："+Winapp2Store.Url,report.Summary,"REMOVESELF 适配为清空允许的文件，保留目录；RegKey 只解析、展示，不执行。"}.Concat(report.Lines),new System.Text.UTF8Encoding(true));message("兼容报告已导出。");}catch(Exception ex){message(ex.Message);}};
  button("Rollback").Click+=(s,e)=>{try{if(useWinapp2)communityStore.Rollback();else store.Rollback();refresh();changed();message("已回退，重新扫描后生效。");}catch(Exception ex){message(ex.Message);}};
  button("AddPortable").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description=UiText.T("选择便携或自定义安装目录")})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){if(!settings.PortableDirectories.Contains(d.SelectedPath,StringComparer.OrdinalIgnoreCase))settings.PortableDirectories.Add(d.SelectedPath);persistSettings();refresh();message("目录已添加，下次手动扫描时检查。");}};button("RemovePortable").Click+=(s,e)=>{var selected=portable.SelectedItem as string;if(selected!=null){settings.PortableDirectories.Remove(selected);persistSettings();refresh();}};
  button("ChooseRecovery").Click+=(s,e)=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description=UiText.T("选择文件备份保存目录；其他盘可释放 C 盘空间")})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)text("RecoveryPath").Text=d.SelectedPath;};button("SaveRecovery").Click+=(s,e)=>{try{string p=Path.GetFullPath(text("RecoveryPath").Text);if(p.StartsWith("\\\\")||!Directory.Exists(p)||!Engine.SafeAncestors(Path.Combine(p,"probe")))throw new IOException("请选择可验证的本地现有目录");settings.RecoveryDirectory=p;persistSettings();changed();message("备份位置已保存。");}catch(Exception ex){message(ex.Message);}};
  button("OpenRecovery").Click+=(s,e)=>{try{BackupFolders.Open(text("RecoveryPath").Text);}catch(Exception ex){message("打开备份位置失败："+ex.Message);}};
  button("RestoreFiles").Click+=async(s,e)=>{var d=new OpenFileDialog{Filter=UiText.T("澄净文件备份 (*.csbackup)|*.csbackup"),Title=UiText.T("选择文件备份索引")};if(d.ShowDialog(owner)!=true)return;if(UiText.Show(owner,"恢复本机、本账户的文件备份，已有文件保留。成功恢复并校验后会自动清除对应备份，未恢复内容仍保留。", "恢复文件",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;restoring=true;administrator.IsEnabled=false;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=false;progress("正在校验并恢复文件…");try{var result=await Task.Run(()=>FileRecovery.RestoreDetailed(d.FileName,true));message("已恢复 "+result.Restored+" 个文件 · 清除 "+result.Cleared+" 份备份 · 保留 "+result.Pending+" 份"+(result.Failed>0?" · 失败 "+result.Failed+" 项":"")+"。");status.ToolTip=String.Join("\n",result.Errors);changed();}catch(Exception ex){message("恢复停止："+ex.Message);}finally{restoring=false;administrator.IsEnabled=!App.IsAdmin()&&restartAdministrator!=null;button("RestoreFiles").IsEnabled=button("Purge").IsEnabled=true;}};
  button("Purge").Click+=(s,e)=>{var d=new OpenFileDialog{Filter=UiText.T("澄净文件备份 (*.csbackup)|*.csbackup"),Title=UiText.T("选择要清空的备份")};if(d.ShowDialog(owner)!=true)return;try{var entries=FileRecovery.Read(d.FileName);if(UiText.Show(owner,"永久删除该批 "+entries.Count+" 个备份文件。此后不能从该备份恢复。", "清空备份",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;FileRecovery.Purge(d.FileName);message("该批备份已清空。");}catch(Exception ex){message(ex.Message);}};
  string registryDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ClearSpace","RegistryBackups");
  button("OpenRegistryBackup").Click+=(s,e)=>{try{if(!Directory.Exists(registryDirectory)){message("还没有注册表备份。");return;}BackupFolders.Open(registryDirectory);}catch(Exception ex){message("打开注册表备份位置失败："+ex.Message);}};
  button("RestoreRegistry").Click+=(s,e)=>{var d=new OpenFileDialog{Title=UiText.T("选择澄净生成的注册表备份"),Filter=UiText.T("澄净注册表备份 (*.json)|*.json"),InitialDirectory=Directory.Exists(registryDirectory)?registryDirectory:AppDomain.CurrentDomain.BaseDirectory};if(d.ShowDialog(owner)!=true)return;if(UiText.Show(owner,"恢复本机备份中的缺失注册表项。已存在的项不会被覆盖。","恢复注册表备份",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;try{int count=RegistryCleaner.Restore(d.FileName);message("已恢复 "+count+" 项注册表；现有项保留。");changed();}catch(Exception ex){message("恢复注册表失败："+ex.Message);}};
  UiMotion.Tabs((TabControl)w.FindName("RulesTabs"));
  return new SettingsView{Root=w,TryLeave=()=>{if(updating){updateStop.Cancel();progress("正在取消更新…");return false;}if(restoring){progress("正在恢复文件，请完成后关闭。");return false;}return true;}};
 }
}
}
